import java.util.Arrays;
import org.apache.commons.math.MathRuntimeException;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Unit tests for MathUtils.factorialDouble
 */
public class MathUtils_factorialDouble_TriageGen0Test {

    private static final double EPSILON = 1e-9;

    @Test
    public void testFactorialDouble_NegativeInput() {
        try {
            MathUtils.factorialDouble(-1);
            fail("Expected MathRuntimeException to be thrown for n < 0");
        } catch (RuntimeException e) {
            // Assuming MathRuntimeException is a subclass of RuntimeException 
            // based on the usage of createIllegalArgumentException
            assertTrue(e.getMessage().contains("must have n >= 0"));
        }
    }










}

