public class MathUtils_factorialDouble_TriageGen0Test {

    private static final double EPSILON = 1e-9;





    @Test
    public void testFactorialDouble_SmallN() {
        // Test values within the n < 21 path (using exact factorial)
        assertEquals(1.0, MathUtils.factorialDouble(1), EPSILON);
        assertEquals(2.0, MathUtils.factorialDouble(2), EPSILON);
        assertEquals(6.0, MathUtils.factorialDouble(3), EPSILON);
        assertEquals(120.0, MathUtils.factorialDouble(5), EPSILON);
        assertEquals(3628800.0, MathUtils.factorialDouble(10), EPSILON);
