package org.apache.commons.math.util;

import java.io.*;
import java.math.*;
import java.math.BigDecimal;
import java.math.BigInteger;
import java.util.*;
import java.util.Arrays;
import org.apache.commons.math.MathRuntimeException;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Unit tests for MathUtils.factorialDouble
 */
public class MathUtils_factorialDouble_TriageGen0Test {

    private static final double EPSILON = 1e-9;









    @Test
    public void testFactorialDouble_LargeN() {
        // Test values in the n >= 21 branch (using exp(factorialLog(n)))
        // 21! is approx 5.109094217170944e+19
        double n21 = MathUtils.factorialDouble(21);
        assertTrue(n21 > 0);

        // Check 25!
        // 25! = 15511210043330985984000000
        double expected25 = 1.5511210043330986E25;
        assertEquals(expected25, MathUtils.factorialDouble(25), expected25 * 1e-15);
    }


}

